(6649592, 993255, 140518, '<td valign="top">Nice, but I wish the lighthouse was sharper.</td>', 'Nice, but I wish the lighthouse was sharper.', '2012-01-19 13:08:50.000000', NULL, 1),
(6649673, 993422, 63244, '<td valign="top">If this doesn''t get blue, I''ll be shocked! My fave of the challenge. 10 Composition, color and detail are all just wonderful!!! Well done!</td>', 'If this doesn''t get blue, I''ll be shocked! My fave of the challenge. 10 Composition, color and detail are all just wonderful!!! Well done!', '2012-01-19 15:04:57.000000', NULL, 1),
