(6649723, 993305, 63244, '<td valign="top">This is actually quite cool, but I fear the "stock lovers" on DPC won''t give it the credit it deserves.</td>', 'This is actually quite cool, but I fear the "stock lovers" on DPC won''t give it the credit it deserves.', '2012-01-19 16:38:07.000000', NULL, 1),
