(6649759, 993323, 12611, '<td valign="top">well done; has that exotic African or Australian tree feel. Or I could be way off base- but the mood and lighting are great.</td>', 'well done; has that exotic African or Australian tree feel. Or I could be way off base- but the mood and lighting are great.', '2012-01-19 17:49:58.000000', NULL, 1),
(6649760, 993423, 12611, '<td valign="top">Lit up like a Christmas tree! Looks like I would picture a scandanavian village, but I could be way off base. Good shadows too.</td>', 'Lit up like a Christmas tree! Looks like I would picture a scandanavian village, but I could be way off base. Good shadows too.', '2012-01-19 17:51:14.000000', NULL, 1),
(6649761, 992985, 12611, '<td valign="top">Looks like a Pennystreet perspective and glimpse- but Hey I could be wrong. I always enjoy these slice of life city shots!</td>', 'Looks like a Pennystreet perspective and glimpse- but Hey I could be wrong. I always enjoy these slice of life city shots!', '2012-01-19 17:53:28.000000', NULL, 1),
(6649764, 993425, 12611, '<td valign="top">This has great soul, for some reason, the framing and texture works well. The peripheral lights in the dark negative frame space are a touch distracting.</td>', 'This has great soul, for some reason, the framing and texture works well. The peripheral lights in the dark negative frame space are a touch distracting.', '2012-01-19 17:54:47.000000', NULL, 1),
(6649765, 992610, 12611, '<td valign="top">Great touches with the flower and the house- the great sky- one of my faves so far. This looks like what I would imagine the South looks like in Winter.</td>', 'Great touches with the flower and the house- the great sky- one of my faves so far. This looks like what I would imagine the South looks like in Winter.', '2012-01-19 17:55:54.000000', NULL, 1),
