(6649982, 993422, 10785, '<td valign="top">Definite grammar problem with the title. You used past tense then switched to present tense. But that doesn''t affect my vote. I just wanted to be a grammar nazi! For the picture. I love the brown murky water and the dark cloudy sky. It looks great with the saturated colors. The green boat, the blue tarp and the flags all pop!</td>', 'Definite grammar problem with the title. You used past tense then switched to present tense. But that doesn''t affect my vote. I just wanted to be a grammar nazi! For the picture. I love the brown murky water and the dark cloudy sky. It looks great with the saturated colors. The green boat, the blue tarp and the flags all pop!', '2012-01-19 22:29:24.000000', NULL, 1),
(6650194, 993255, 67237, '<td valign="top">shaky tripod?</td>', 'shaky tripod?', '2012-01-20 01:13:36.000000', NULL, 1),
(6650449, 993356, 114225, '<td valign="top">Lovely idea. I''m not a fan of the flashlight bouncing through, it seems to take away from the grandness of the hills.</td>', 'Lovely idea. I''m not a fan of the flashlight bouncing through, it seems to take away from the grandness of the hills.', '2012-01-20 09:54:45.000000', NULL, 1),
