(6653537, 993456, 61396, '<td valign="top">nice grainy green and black wires to interrupt it.</td>', 'nice grainy green and black wires to interrupt it.', '2012-01-24 02:16:36.000000', NULL, 1),
(6653538, 992733, 61396, '<td valign="top">those square crops are really huge, Doc.</td>', 'those square crops are really huge, Doc.', '2012-01-24 02:17:45.000000', NULL, 1),
(6653539, 993171, 61396, '<td valign="top">too little noise to my taste (not voting though)</td>', 'too little noise to my taste (not voting though)', '2012-01-24 02:19:01.000000', NULL, 1),
(6653540, 992742, 61396, '<td valign="top">thank you for your vision.</td>', 'thank you for your vision.', '2012-01-24 02:26:51.000000', NULL, 1),
(6653579, 993414, 143238, '<td valign="top">Lovely!</td>', 'Lovely!', '2012-01-24 04:53:42.000000', NULL, 1),
(6653618, 993255, 12611, '<td valign="top">a stark, miniature end of the known world kind of feel.</td>', 'a stark, miniature end of the known world kind of feel.', '2012-01-24 08:36:02.000000', NULL, 1),
(6653619, 992733, 12611, '<td valign="top">Although it is dramatic, the bright yellow orange may be distracting. I do give the image high marks though, for the pillowy sky and wispy tree branches.</td>', 'Although it is dramatic, the bright yellow orange may be distracting. I do give the image high marks though, for the pillowy sky and wispy tree branches.', '2012-01-24 08:37:56.000000', NULL, 1),
(6653621, 993414, 12611, '<td valign="top">Excellent silhouetting. and the border adds to the holloywood-esque feel of the shot.</td>', 'Excellent silhouetting. and the border adds to the holloywood-esque feel of the shot.', '2012-01-24 08:38:59.000000', NULL, 1),
(6653622, 993463, 12611, '<td valign="top">you have probably heard it too much by now- but you have to make this bigger.</td>', 'you have probably heard it too much by now- but you have to make this bigger.', '2012-01-24 08:39:51.000000', NULL, 1),
(6653623, 992577, 12611, '<td valign="top">This a great version, or in the style rather, of a shot I entered in this very challenge! But you succeeded where I failed, you have great contrast, and great detail in the branch as it hits the sky in the focal point of the shot- and a great title!</td>', 'This a great version, or in the style rather, of a shot I entered in this very challenge! But you succeeded where I failed, you have great contrast, and great detail in the branch as it hits the sky in the focal point of the shot- and a great title!', '2012-01-24 08:41:15.000000', NULL, 1),
(6653624, 993413, 12611, '<td valign="top">Great fence posts- well done in total.</td>', 'Great fence posts- well done in total.', '2012-01-24 08:41:55.000000', NULL, 1),
(6653630, 992382, 12611, '<td valign="top">I picture this as the opening shot of a movie, the cinematic moment just when the helicopter pulls up and back...</td>', 'I picture this as the opening shot of a movie, the cinematic moment just when the helicopter pulls up and back...', '2012-01-24 09:06:05.000000', NULL, 1),
(6653633, 993456, 12611, '<td valign="top">very well done. like scratches in the margins of an old novel written in a foreign language.</td>', 'very well done. like scratches in the margins of an old novel written in a foreign language.', '2012-01-24 09:06:58.000000', NULL, 1),
(6653634, 993306, 12611, '<td valign="top">serene. The perspective of the reeds is nice.</td>', 'serene. The perspective of the reeds is nice.', '2012-01-24 09:08:43.000000', NULL, 1),
(6653637, 993422, 12611, '<td valign="top">great flags and specs of color.</td>', 'great flags and specs of color.', '2012-01-24 09:10:23.000000', NULL, 1),
(6653638, 993461, 12611, '<td valign="top">There is a scene from a movie with Jack Nicholson, A 90''s movie, "Wolf" and this reminds me of the opening scene- except for the lights. There is also a great holiday feeling to this shot, from a different perspective.</td>', 'There is a scene from a movie with Jack Nicholson, A 90''s movie, "Wolf" and this reminds me of the opening scene- except for the lights. There is also a great holiday feeling to this shot, from a different perspective.', '2012-01-24 09:13:49.000000', NULL, 1),
(6653639, 992969, 12611, '<td valign="top">The boats and water ripples make this shot.</td>', 'The boats and water ripples make this shot.', '2012-01-24 09:14:20.000000', NULL, 1),
(6653651, 993428, 12611, '<td valign="top">I had to throw this in photoshop and shadow highlight it to reveal the underlying trees, because my monitor is so dark. I like it, think its a good take on this challenge.</td>', 'I had to throw this in photoshop and shadow highlight it to reveal the underlying trees, because my monitor is so dark. I like it, think its a good take on this challenge.', '2012-01-24 09:18:54.000000', NULL, 1),
