(6653663, 992656, 50641, '<td valign="top">looks familiar</td>', 'looks familiar', '2012-01-24 09:34:52.000000', NULL, 1),
(6653675, 993257, 142473, '<td valign="top">Cool take on the challenge.  The image is heavy on the right side, but that''s the point of this image.<br/> <br/>My only qualm is that the image looks a good bit over-processed.  Otherwise cool!</td>', 'Cool take on the challenge.  The image is heavy on the right side, but that''s the point of this image. My only qualm is that the image looks a good bit over-processed.  Otherwise cool!', '2012-01-24 09:52:04.000000', NULL, 1),
