(6653734, 993305, 11769, '<td valign="top">Beautiful and dark</td>', 'Beautiful and dark', '2012-01-24 11:16:12.000000', NULL, 1),
(6653736, 993456, 11769, '<td valign="top">Perfect! 10</td>', 'Perfect! 10', '2012-01-24 11:16:53.000000', NULL, 1),
