(6653829, 992733, 118154, '<td valign="top">What a sky !</td>', 'What a sky !', '2012-01-24 12:53:23.000000', NULL, 1),
(6653830, 993252, 118154, '<td valign="top">Too much darkness on my screen.</td>', 'Too much darkness on my screen.', '2012-01-24 12:54:17.000000', NULL, 1),
